/* Sally Face (541570): тема главного экрана «Карандашная тревога».

   Холодный сине-серый, нарисованный от руки мир. Кнопка — холодная бумага,
   акцент — нервная карандашная каракуля вместо ровной линии, цвета волос Салли.

   Выбрана владельцем 26 сентября по макету. Подключается после web/hub.css;
   каждое правило привязано к игре (body.theme-sallyface), затемнение той же
   плотности, что у всех, меняется только оттенок. */

/* Оттенок затемнения выровнен по яркости с общим (2,4,7): тёплый цвет при той
   же прозрачности светлее синеватого, и подписи на светлом кадре теряли до
   0,1 контраста. Тон остаётся, читаемость — как у всех. */
body.theme-sallyface .scrim { background:
    linear-gradient(92deg, rgba(2,4,6,.94) 0%, rgba(2,4,6,.82) 13%, rgba(2,4,6,.54) 26%, rgba(2,4,6,.18) 40%, rgba(2,4,6,0) 54%),
    linear-gradient(0deg, rgba(2,4,6,.96) 0%, rgba(2,4,6,.78) 9%, rgba(2,4,6,.43) 18%, rgba(2,4,6,.16) 29%, rgba(2,4,6,0) 40%),
    linear-gradient(180deg, rgba(2,4,6,.75) 0%, rgba(2,4,6,.30) 8%, rgba(2,4,6,0) 16%); }
body.theme-sallyface #cardCopyFrame { position: relative; border-left: 2px solid transparent;
  padding-left: 1.4rem; margin-left: -1.4rem; }
body.theme-sallyface .label { color: #a9c9da; text-shadow: 0 0 14px rgba(120,170,200,.3); }
body.theme-sallyface .fact-sep { background: linear-gradient(to bottom, transparent, rgba(169,201,218,.4), transparent); }
body.theme-sallyface .continue { background: linear-gradient(135deg, #eef2f3 0%, #cfd8dc 100%); color: #12181b;
  box-shadow: 0 .4rem 1.6rem rgba(0,0,0,.6); }
body.theme-sallyface .continue .tri { color: #12181b; }
body.theme-sallyface .continue:hover, body.theme-sallyface .continue:focus-visible { background: #f7fafb;
  box-shadow: 0 .4rem 2rem rgba(0,0,0,.6); }
